	/**
	 * Default Constructor
	 */
    public SensorInstanceService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new SensorInstanceEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(SensorInstanceRepository.class) );
		this.validator		= applicationContext.getBean(SensorInstanceValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		SensorInstance
	 */
		public SensorInstance createSensorInstance( CreateSensorInstanceCommand command ) {

		SensorInstance entity = new SensorInstance();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setSensorInstanceId( command.getSensorInstanceId() );
            entity.setName( command.getName() );
            entity.setUnit( command.getUnit() );
            entity.setSamplingIntervalMs( command.getSamplingIntervalMs() );
            entity.setSensorType( command.getSensorType() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of SensorInstance {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateSensorInstanceCommand
	 * @return		SensorInstance
	 */
	public SensorInstance updateSensorInstance( UpdateSensorInstanceCommand command ) {

		SensorInstance entity = new SensorInstance();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setSensorInstanceId( command.getSensorInstanceId() );
            entity.setName( command.getName() );
            entity.setUnit( command.getUnit() );
            entity.setSamplingIntervalMs( command.getSamplingIntervalMs() );
            entity.setDevice( command.getDevice() );
            entity.setTelemetryStreams( command.getTelemetryStreams() );
            entity.setSensorType( command.getSensorType() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of SensorInstance {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteSensorInstanceCommand
	 */
	public void delete( DeleteSensorInstanceCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getSensorInstanceId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of SensorInstance {0} ", id );

	}

	/**
	 * Method to retrieve the SensorInstance via SensorInstanceFetchOneSummary
	 * @param 	summary SensorInstanceFetchOneSummary
	 * @return 	SensorInstanceFetchOneResponse
	 */
	public SensorInstance getSensorInstance( SensorInstanceFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "SensorInstanceFetchOneSummary arg cannot be null" );

		SensorInstance entity = null;
		UUID id = summary.getSensorInstanceId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a SensorInstance using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all SensorInstances
	 *
	 * @return 	List<SensorInstance>
	 */
    public List<SensorInstance> getAllSensorInstance() {
		List<SensorInstance> list = projector.findAll( new FindAllSensorInstanceQuery() );
		return list;
	}

	/**
	 * assign Device on SensorInstance
	 * @param		command AssignDeviceToSensorInstanceCommand
	 */
	public void assignDevice( AssignDeviceToSensorInstanceCommand command ) {
		// --------------------------------------
		// best to validate the command now
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.assignDevice(command.getChildId(), command.getAssignment());

	}

	/**
	 * unAssign Device on SensorInstance
	 * @param		command UnAssignDeviceFromSensorInstanceCommand
	 */
	public void unAssignDevice( UnAssignDeviceFromSensorInstanceCommand command ) {

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.unAssignDevice(command.getChildId());
	}
	

	/**
	 * add TelemetryStream to TelemetryStreams
	 * @param		command AssignTelemetryStreamsToSensorInstanceCommand
	 */
	public void addToTelemetryStreams( AssignTelemetryStreamsToSensorInstanceCommand command ) {

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.addToTelemetryStreams(command.getParentId(), command.getChildIds());
	}

	/**
	 * remove TelemetryStream from TelemetryStreams
	 * @param		command RemoveTelemetryStreamsFromSensorInstanceCommand
	 */
	public void removeFromTelemetryStreams( RemoveTelemetryStreamsFromSensorInstanceCommand command )  {
		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.removeFromTelemetryStreams(command.getParentId(), command.getChildIds());
	}




